// BOXTIMER PRO v6 — Continuous Background WAV Track Engine
const REAL_SINGLE_BELL_B64 = "";
const REAL_DOUBLE_BELL_B64 = "";
const REAL_WHISTLE_B64 = "";

function base64ToArrayBuffer(b64) {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes.buffer;
}

class BoxingAudioEngine {
  constructor() {
    this.ctx = null;
    this.compressor = null;
    this.muted = false;
    this.trackSampleRate = 16000;

    // Elemento <audio> nativo que toca a faixa contínua do treino (não congela em 2º plano no iOS)
    this.workoutAudio = new Audio();
    this.workoutAudio.setAttribute('playsinline', 'true');
    this.workoutAudio.preload = 'auto';
    this.currentBlobUrl = null;

    // Buffers PCM Int16 (16kHz) para montagem instantânea da faixa de treino
    this.pcmSingleBell = this._createFallbackBellPcm(1);
    this.pcmDoubleBell = this._createFallbackBellPcm(2);
    this.pcmWhistle = this._createFallbackWhistlePcm();
    this.pcmPipLow = this._createPipPcm(880, 0.11);
    this.pcmPipHigh = this._createPipPcm(1046.5, 0.12);
    this.pcmPrepPip = this._createPipPcm(660, 0.11);

    this.singleBellBuffer = null;
    this.doubleBellBuffer = null;
    this.whistleBuffer = null;

    this.preloadRealAudio();
  }

  preloadRealAudio() {
    const OfflineCtx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!OfflineCtx) return;

    const decodeOne = (b64) =>
      new Promise((resolve) => {
        try {
          const offlineCtx = new OfflineCtx(1, 1, 44100);
          const ab = base64ToArrayBuffer(b64);
          offlineCtx.decodeAudioData(
            ab,
            (decoded) => resolve(decoded),
            () => resolve(null)
          );
        } catch (_) {
          resolve(null);
        }
      });

    this.decodePromise = Promise.all([
      decodeOne(REAL_SINGLE_BELL_B64),
      decodeOne(REAL_DOUBLE_BELL_B64),
      decodeOne(REAL_WHISTLE_B64)
    ]).then(([singleBuf, doubleBuf, whistleBuf]) => {
      if (singleBuf) {
        this.singleBellBuffer = singleBuf;
        this.pcmSingleBell = this._audioBufferToPcm16(singleBuf, 1.65);
      }
      if (doubleBuf) {
        this.doubleBellBuffer = doubleBuf;
        this.pcmDoubleBell = this._audioBufferToPcm16(doubleBuf, 1.65);
      }
      if (whistleBuf) {
        this.whistleBuffer = whistleBuf;
        this.pcmWhistle = this._audioBufferToPcm16(whistleBuf, 1.45);
      }
    });
  }

  init() {
    if ('audioSession' in navigator) {
      try {
        navigator.audioSession.type = 'playback';
      } catch (_) {}
    }

    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
        this.compressor = this.ctx.createDynamicsCompressor();
        this.compressor.threshold.setValueAtTime(-14, this.ctx.currentTime);
        this.compressor.knee.setValueAtTime(6, this.ctx.currentTime);
        this.compressor.ratio.setValueAtTime(12, this.ctx.currentTime);
        this.compressor.attack.setValueAtTime(0.001, this.ctx.currentTime);
        this.compressor.release.setValueAtTime(0.15, this.ctx.currentTime);
        this.compressor.connect(this.ctx.destination);
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  _audioBufferToPcm16(audioBuffer, gain = 1.5) {
    const srcRate = audioBuffer.sampleRate;
    const dstRate = this.trackSampleRate;
    const srcData = audioBuffer.getChannelData(0);
    const ratio = srcRate / dstRate;
    const dstLen = Math.floor(srcData.length / ratio);
    const out = new Int16Array(dstLen);

    for (let i = 0; i < dstLen; i++) {
      const srcIdx = i * ratio;
      const idx0 = Math.floor(srcIdx);
      const frac = srcIdx - idx0;
      const s0 = srcData[idx0] || 0;
      const s1 = srcData[Math.min(srcData.length - 1, idx0 + 1)] || 0;
      const sample = (s0 + frac * (s1 - s0)) * gain;
      const clipped = Math.tanh(sample);
      out[i] = Math.max(-32767, Math.min(32767, Math.round(clipped * 32600)));
    }
    return out;
  }

  _createPipPcm(freq, durationSec) {
    const sr = this.trackSampleRate;
    const len = Math.floor(sr * durationSec);
    const out = new Int16Array(len);
    for (let i = 0; i < len; i++) {
      const t = i / sr;
      const env = t < 0.008 ? t / 0.008 : Math.exp(-(t - 0.008) / 0.035);
      const val = Math.sin(2 * Math.PI * freq * t) * env * 0.55;
      out[i] = Math.round(val * 32000);
    }
    return out;
  }

  _createFallbackBellPcm(strikes = 1) {
    const sr = this.trackSampleRate;
    const duration = strikes === 1 ? 1.6 : 1.9;
    const len = Math.floor(sr * duration);
    const out = new Int16Array(len);
    const offsets = strikes === 1 ? [0] : [0, Math.floor(0.24 * sr)];
    const freqs = [964, 1342, 1349, 1876, 2465, 3118];

    offsets.forEach((off) => {
      for (let i = off; i < len; i++) {
        const t = (i - off) / sr;
        const env = Math.exp(-t / 0.45);
        let sum = 0;
        for (let f of freqs) sum += Math.sin(2 * Math.PI * f * t);
        const cur = out[i] / 32767 + (sum / freqs.length) * env * 0.9;
        out[i] = Math.max(-32767, Math.min(32767, Math.round(Math.tanh(cur * 2) * 32000)));
      }
    });
    return out;
  }

  _createFallbackWhistlePcm() {
    const sr = this.trackSampleRate;
    const len = Math.floor(sr * 0.65);
    const out = new Int16Array(len);
    for (let i = 0; i < len; i++) {
      const t = i / sr;
      const env = t < 0.02 ? t / 0.02 : t > 0.55 ? (0.65 - t) / 0.1 : 1.0;
      const trill = 1 + 0.02 * Math.sin(2 * Math.PI * 30 * t);
      const val = Math.sin(2 * Math.PI * 2900 * trill * t) * env * 0.85;
      out[i] = Math.round(val * 32000);
    }
    return out;
  }

  /**
   * Monta um único arquivo WAV em memória contendo TODOS os gongos, apitos e bips
   * da sessão atual até o fim do treino e inicia no elemento <audio> nativo.
   */
  startWorkoutTrack(segments, warnLast10) {
    this.init();

    const sr = this.trackSampleRate;
    const lastSeg = segments[segments.length - 1];
    const totalDurationMs = (lastSeg ? lastSeg.startMs + lastSeg.durationMs : 1000) + 500;
    const totalSamples = Math.max(sr, Math.ceil((totalDurationMs / 1000) * sr));

    const pcm = new Int16Array(totalSamples);

    // Sinal sub-audível contínuo (-62dB) para impedir que o iOS considere a faixa como 'silêncio digital'
    for (let i = 0; i < totalSamples; i += 32) {
      pcm[i] = 16;
      if (i + 16 < totalSamples) pcm[i + 16] = -16;
    }

    const stamp = (srcPcm, atMs) => {
      if (!srcPcm || atMs < 0) return;
      const startIdx = Math.floor((atMs / 1000) * sr);
      const endIdx = Math.min(totalSamples, startIdx + srcPcm.length);
      for (let i = startIdx; i < endIdx; i++) {
        const mixed = pcm[i] + srcPcm[i - startIdx];
        pcm[i] = mixed > 32767 ? 32767 : mixed < -32767 ? -32767 : mixed;
      }
    };

    segments.forEach((seg) => {
      if (seg.playStartSound) {
        if (seg.phase === 'PREP') {
          stamp(this.pcmPrepPip, seg.startMs);
        } else if (seg.phase === 'WORK') {
          stamp(this.pcmSingleBell, seg.startMs);
        } else if (seg.phase === 'REST' || seg.phase === 'FINISHED') {
          stamp(this.pcmDoubleBell, seg.startMs);
        }
      }

      if (seg.phase === 'FINISHED') return;

      if (seg.phase === 'WORK' && warnLast10 && seg.durationMs >= 10000) {
        const warnAtMs = seg.startMs + seg.durationMs - 10000;
        stamp(this.pcmWhistle, warnAtMs);
      }

      for (let sec = 3; sec >= 1; sec--) {
        const secMs = sec * 1000;
        if (seg.durationMs >= secMs + 200) {
          const pipAtMs = seg.startMs + seg.durationMs - secMs;
          stamp(sec === 1 ? this.pcmPipHigh : this.pcmPipLow, pipAtMs);
        }
      }
    });

    const wavHeader = this._createWavHeader(totalSamples * 2, sr);
    const wavBlob = new Blob([wavHeader, pcm.buffer], { type: 'audio/wav' });

    if (this.currentBlobUrl) {
      URL.revokeObjectURL(this.currentBlobUrl);
    }
    this.currentBlobUrl = URL.createObjectURL(wavBlob);

    this.workoutAudio.src = this.currentBlobUrl;
    this.workoutAudio.muted = this.muted;
    this.workoutAudio.currentTime = 0;
    this.workoutAudio.play().catch((err) => {
      console.warn('Aviso ao iniciar áudio contínuo:', err);
    });
  }

  stopWorkoutTrack() {
    try {
      this.workoutAudio.pause();
    } catch (_) {}
  }

  _createWavHeader(dataByteLength, sampleRate) {
    const header = new ArrayBuffer(44);
    const view = new DataView(header);
    const writeStr = (offset, str) => {
      for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i));
    };
    writeStr(0, 'RIFF');
    view.setUint32(4, 36 + dataByteLength, true);
    writeStr(8, 'WAVE');
    writeStr(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeStr(36, 'data');
    view.setUint32(40, dataByteLength, true);
    return header;
  }

  _playPcmPreview(pcm16) {
    if (this.muted || !pcm16) return;
    this.init();
    const wavHeader = this._createWavHeader(pcm16.length * 2, this.trackSampleRate);
    const blob = new Blob([wavHeader, pcm16.buffer], { type: 'audio/wav' });
    const url = URL.createObjectURL(blob);
    const previewAudio = new Audio(url);
    previewAudio.setAttribute('playsinline', 'true');
    previewAudio.play().finally(() => {
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    });
  }

  playGong(strikes = 1) {
    const run = () => {
      this._playPcmPreview(strikes >= 2 ? this.pcmDoubleBell : this.pcmSingleBell);
    };
    if (this.singleBellBuffer || !this.decodePromise) {
      run();
    } else {
      this.decodePromise.then(run);
    }
  }

  playTenSecondWarning() {
    const run = () => {
      this._playPcmPreview(this.pcmWhistle);
    };
    if (this.whistleBuffer || !this.decodePromise) {
      run();
    } else {
      this.decodePromise.then(run);
    }
  }
}

// ============================================================================
// Aplicação Principal do Timer
// ============================================================================

const STORAGE_KEY = 'boxtimer_pro_config_v1';

const DEFAULT_CONFIG = {
  roundSeconds: 180,
  restSeconds: 60,
  totalRounds: 5,
  prepSeconds: 5,
  warnLast10: true
};

const THEME_COLORS = {
  'state-idle': '#090b10',
  'state-prep': '#082f49',
  'state-work': '#043927',
  'state-warning': '#78350f',
  'state-rest': '#691212',
  'state-finished': '#172554'
};

class BoxingTimerApp {
  constructor() {
    this.audio = new BoxingAudioEngine();
    this.config = this.loadConfig();
    this.draftConfig = { ...this.config };

    this.phase = 'IDLE';
    this.currentRound = 1;
    this.isRunning = false;
    this.phaseDurationMs = this.config.roundSeconds * 1000;
    this.remainingMs = this.phaseDurationMs;
    this.timeline = [];
    this.trackStartWallTime = 0;
    this.activeSegmentIndex = -1;
    this.rafId = null;
    this.bgIntervalId = null;
    this.wakeLock = null;

    this.cacheDOM();
    this.bindEvents();
    this.setupDialogLightDismissFallback();
    this.renderRoundDots();
    this.updateSummaryUI();
    this.syncUI();
  }

  loadConfig() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return { ...DEFAULT_CONFIG, ...JSON.parse(saved) };
      }
    } catch (e) {
      console.warn('Não foi possível ler configurações salvas:', e);
    }
    return { ...DEFAULT_CONFIG };
  }

  saveConfig() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.config));
    } catch (e) {
      console.warn('Não foi possível salvar configurações:', e);
    }
  }

  cacheDOM() {
    this.body = document.body;
    this.themeMeta = document.getElementById('themeColorMeta');
    this.flashOverlay = document.getElementById('flashOverlay');

    this.phaseBadge = document.getElementById('phaseBadge');
    this.roundDisplay = document.getElementById('roundDisplay');
    this.roundDots = document.getElementById('roundDots');
    this.timeDisplay = document.getElementById('timeDisplay');
    this.progressBar = document.getElementById('progressBar');

    this.summaryPill = document.getElementById('summaryPill');
    this.summaryRound = document.getElementById('summaryRound');
    this.summaryRest = document.getElementById('summaryRest');
    this.summaryTotal = document.getElementById('summaryTotal');
    this.summaryWarn = document.getElementById('summaryWarn');
    this.summaryWarnSep = document.getElementById('summaryWarnSep');

    this.startPauseBtn = document.getElementById('startPauseBtn');
    this.startPauseLabel = document.getElementById('startPauseLabel');
    this.playIcon = document.getElementById('playIcon');
    this.pauseIcon = document.getElementById('pauseIcon');
    this.resetBtn = document.getElementById('resetBtn');
    this.skipBtn = document.getElementById('skipBtn');

    this.muteBtn = document.getElementById('muteBtn');
    this.soundOnIcon = document.getElementById('soundOnIcon');
    this.soundOffIcon = document.getElementById('soundOffIcon');

    this.settingsDialog = document.getElementById('settingsDialog');
    this.openSettingsBtn = document.getElementById('openSettingsBtn');
    this.closeSettingsBtn = document.getElementById('closeSettingsBtn');
    this.saveSettingsBtn = document.getElementById('saveSettingsBtn');

    this.cfgRoundValue = document.getElementById('cfgRoundValue');
    this.cfgRestValue = document.getElementById('cfgRestValue');
    this.cfgRoundsValue = document.getElementById('cfgRoundsValue');
    this.cfgPrepValue = document.getElementById('cfgPrepValue');
    this.cfgWarnToggle = document.getElementById('cfgWarnToggle');

    this.testBell1Btn = document.getElementById('testBell1Btn');
    this.testBell2Btn = document.getElementById('testBell2Btn');
    this.testWarnBtn = document.getElementById('testWarnBtn');
    this.presetChips = document.querySelectorAll('.preset-chip');
    this.stepBtns = document.querySelectorAll('.step-btn');
  }

  bindEvents() {
    this.startPauseBtn.addEventListener('click', () => {
      this.audio.init();
      this.toggleStartPause();
    });

    this.resetBtn.addEventListener('click', () => {
      this.audio.init();
      this.resetTimer();
    });

    this.skipBtn.addEventListener('click', () => {
      this.audio.init();
      this.skipPhase();
    });

    this.audio.workoutAudio.addEventListener('timeupdate', () => {
      if (this.isRunning) this.tick();
    });

    this.muteBtn.addEventListener('click', () => {
      this.audio.init();
      this.audio.muted = !this.audio.muted;
      this.audio.workoutAudio.muted = this.audio.muted;
      this.muteBtn.classList.toggle('is-muted', this.audio.muted);
      this.soundOnIcon.classList.toggle('hidden', this.audio.muted);
      this.soundOffIcon.classList.toggle('hidden', !this.audio.muted);
    });

    const openModal = () => {
      this.audio.init();
      if (this.isRunning) {
        this.pauseTimer();
      }
      this.draftConfig = { ...this.config };
      this.syncSettingsModalUI();
      this.settingsDialog.showModal();
    };

    this.openSettingsBtn.addEventListener('click', openModal);
    this.summaryPill.addEventListener('click', openModal);
    this.closeSettingsBtn.addEventListener('click', () => this.settingsDialog.close());

    this.stepBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        const action = btn.dataset.action;
        this.handleStepperAction(action);
      });
    });

    this.presetChips.forEach((chip) => {
      chip.addEventListener('click', () => {
        this.draftConfig.roundSeconds = Number(chip.dataset.round);
        this.draftConfig.restSeconds = Number(chip.dataset.rest);
        this.draftConfig.totalRounds = Number(chip.dataset.rounds);
        this.draftConfig.prepSeconds = Number(chip.dataset.prep);
        this.syncSettingsModalUI();
      });
    });

    this.cfgWarnToggle.addEventListener('change', () => {
      this.draftConfig.warnLast10 = this.cfgWarnToggle.checked;
    });

    this.testBell1Btn.addEventListener('click', () => {
      this.audio.playGong(1);
    });

    this.testBell2Btn.addEventListener('click', () => {
      this.audio.playGong(2);
    });

    this.testWarnBtn.addEventListener('click', () => {
      this.audio.playTenSecondWarning();
    });

    this.saveSettingsBtn.addEventListener('click', () => {
      this.config = { ...this.draftConfig };
      this.saveConfig();
      this.settingsDialog.close();
      this.resetTimer();
    });

    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible' && this.isRunning) {
        this.requestWakeLock();
        this.tick();
      }
    });
  }

  setupDialogLightDismissFallback() {
    const dialog = this.settingsDialog;
    if (!('closedBy' in HTMLDialogElement.prototype)) {
      dialog.addEventListener('click', (event) => {
        if (event.target !== dialog) return;
        const rect = dialog.getBoundingClientRect();
        const isDialogContent =
          rect.top <= event.clientY &&
          event.clientY <= rect.top + rect.height &&
          rect.left <= event.clientX &&
          event.clientX <= rect.left + rect.width;

        if (isDialogContent) return;
        dialog.close();
      });
    }
  }

  handleStepperAction(action) {
    const c = this.draftConfig;
    switch (action) {
      case 'round-minus':
        c.roundSeconds = Math.max(15, c.roundSeconds - 15);
        break;
      case 'round-plus':
        c.roundSeconds = Math.min(900, c.roundSeconds + 15);
        break;
      case 'rest-minus':
        c.restSeconds = Math.max(10, c.restSeconds - 5);
        break;
      case 'rest-plus':
        c.restSeconds = Math.min(300, c.restSeconds + 5);
        break;
      case 'rounds-minus':
        c.totalRounds = Math.max(1, c.totalRounds - 1);
        break;
      case 'rounds-plus':
        c.totalRounds = Math.min(30, c.totalRounds + 1);
        break;
      case 'prep-minus':
        c.prepSeconds = Math.max(0, c.prepSeconds - 5);
        break;
      case 'prep-plus':
        c.prepSeconds = Math.min(30, c.prepSeconds + 5);
        break;
    }
    this.syncSettingsModalUI();
  }

  syncSettingsModalUI() {
    const c = this.draftConfig;
    this.cfgRoundValue.textContent = this.formatMMSS(c.roundSeconds * 1000);
    this.cfgRestValue.textContent = this.formatMMSS(c.restSeconds * 1000);
    this.cfgRoundsValue.textContent = String(c.totalRounds);
    this.cfgPrepValue.textContent = `${String(c.prepSeconds).padStart(2, '0')}s`;
    this.cfgWarnToggle.checked = Boolean(c.warnLast10);

    this.presetChips.forEach((chip) => {
      const isMatch =
        Number(chip.dataset.round) === c.roundSeconds &&
        Number(chip.dataset.rest) === c.restSeconds &&
        Number(chip.dataset.rounds) === c.totalRounds;
      chip.classList.toggle('active', isMatch);
    });
  }

  toggleStartPause() {
    if (this.isRunning) {
      this.pauseTimer();
    } else {
      this.startTimer();
    }
  }

  buildRemainingTimeline(isFreshStart) {
    const segments = [];
    let cursorMs = 0;

    const pushSeg = (phase, round, durationMs, fullDurationMs, playStartSound) => {
      segments.push({
        phase,
        round,
        durationMs,
        fullDurationMs,
        startMs: cursorMs,
        playStartSound
      });
      cursorMs += durationMs;
    };

    let startRound = this.currentRound;
    let startPhase = this.phase;

    if (isFreshStart) {
      startRound = 1;
      if (this.config.prepSeconds > 0) {
        pushSeg('PREP', 1, this.config.prepSeconds * 1000, this.config.prepSeconds * 1000, true);
      }
      startPhase = 'WORK';
      this.remainingMs = this.config.roundSeconds * 1000;
    } else {
      const fullDur =
        startPhase === 'PREP'
          ? this.config.prepSeconds * 1000
          : startPhase === 'REST'
          ? this.config.restSeconds * 1000
          : this.config.roundSeconds * 1000;
      pushSeg(startPhase, startRound, this.remainingMs, fullDur, false);

      if (startPhase === 'PREP') {
        pushSeg('WORK', startRound, this.config.roundSeconds * 1000, this.config.roundSeconds * 1000, true);
        if (startRound < this.config.totalRounds) {
          pushSeg('REST', startRound, this.config.restSeconds * 1000, this.config.restSeconds * 1000, true);
        }
      } else if (startPhase === 'WORK') {
        if (startRound < this.config.totalRounds) {
          pushSeg('REST', startRound, this.config.restSeconds * 1000, this.config.restSeconds * 1000, true);
        }
      }
      startRound += 1;
    }

    for (let r = startRound; r <= this.config.totalRounds; r++) {
      pushSeg('WORK', r, this.config.roundSeconds * 1000, this.config.roundSeconds * 1000, true);
      if (r < this.config.totalRounds) {
        pushSeg('REST', r, this.config.restSeconds * 1000, this.config.restSeconds * 1000, true);
      }
    }

    pushSeg('FINISHED', this.config.totalRounds, 2200, 2200, true);

    return segments;
  }

  startTimer(forcePlayFirstSound = false) {
    if (this.phase === 'FINISHED') {
      this.resetTimer();
    }

    const isFreshStart = this.phase === 'IDLE';
    this.timeline = this.buildRemainingTimeline(isFreshStart);
    if (forcePlayFirstSound && this.timeline.length > 0) {
      this.timeline[0].playStartSound = true;
    }

    this.activeSegmentIndex = 0;
    const firstSeg = this.timeline[0];
    this.phase = firstSeg.phase;
    this.currentRound = firstSeg.round;
    this.remainingMs = firstSeg.durationMs;
    this.phaseDurationMs = firstSeg.fullDurationMs;

    this.isRunning = true;
    this.trackStartWallTime = Date.now();

    this.audio.startWorkoutTrack(this.timeline, this.config.warnLast10);

    this.requestWakeLock();
    this.updateMediaSession();

    if (this.bgIntervalId) clearInterval(this.bgIntervalId);
    this.bgIntervalId = setInterval(() => this.tick(), 200);

    this.syncUI();
    this.tick();
  }

  pauseTimer() {
    this.isRunning = false;
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    if (this.bgIntervalId) {
      clearInterval(this.bgIntervalId);
      this.bgIntervalId = null;
    }
    this.audio.stopWorkoutTrack();
    this.releaseWakeLock();
    this.syncUI();
  }

  resetTimer() {
    this.pauseTimer();
    this.phase = 'IDLE';
    this.currentRound = 1;
    this.phaseDurationMs = this.config.roundSeconds * 1000;
    this.remainingMs = this.phaseDurationMs;
    this.timeline = [];
    this.activeSegmentIndex = -1;
    this.renderRoundDots();
    this.updateSummaryUI();
    this.syncUI();
  }

  skipPhase() {
    const wasRunning = this.isRunning;
    if (wasRunning) {
      this.pauseTimer();
    }

    if (this.phase === 'IDLE' || this.phase === 'PREP') {
      this.phase = 'WORK';
      this.currentRound = 1;
      this.phaseDurationMs = this.config.roundSeconds * 1000;
      this.remainingMs = this.phaseDurationMs;
    } else if (this.phase === 'WORK') {
      if (this.currentRound < this.config.totalRounds) {
        this.phase = 'REST';
        this.phaseDurationMs = this.config.restSeconds * 1000;
        this.remainingMs = this.phaseDurationMs;
      } else {
        this.phase = 'FINISHED';
        this.remainingMs = 0;
        this.audio.playGong(2);
        this.renderRoundDots();
        this.syncUI();
        return;
      }
    } else if (this.phase === 'REST') {
      this.currentRound += 1;
      this.phase = 'WORK';
      this.phaseDurationMs = this.config.roundSeconds * 1000;
      this.remainingMs = this.phaseDurationMs;
    } else if (this.phase === 'FINISHED') {
      this.resetTimer();
      return;
    }

    this.renderRoundDots();
    this.syncUI();

    if (wasRunning) {
      this.startTimer(true);
    }
  }

  tick() {
    if (!this.isRunning || this.timeline.length === 0) return;

    const wallElapsedMs = Math.max(0, Date.now() - this.trackStartWallTime);
    const audioEl = this.audio.workoutAudio;
    let elapsedMs = wallElapsedMs;

    if (audioEl && !audioEl.paused && audioEl.currentTime > 0) {
      const audioMs = audioEl.currentTime * 1000;
      if (Math.abs(audioMs - wallElapsedMs) < 1500) {
        elapsedMs = audioMs;
      }
    }

    let segIdx = this.timeline.findIndex(
      (s) => elapsedMs >= s.startMs && elapsedMs < s.startMs + s.durationMs
    );
    if (segIdx === -1) {
      segIdx = this.timeline.length - 1;
    }

    const seg = this.timeline[segIdx];

    if (segIdx !== this.activeSegmentIndex) {
      this.activeSegmentIndex = segIdx;
      this.phase = seg.phase;
      this.currentRound = seg.round;
      this.phaseDurationMs = seg.fullDurationMs;
      this.triggerFlash();
      this.renderRoundDots();
      this.updateMediaSession();
    }

    if (seg.phase === 'FINISHED') {
      this.remainingMs = 0;
      this.isRunning = false;
      if (this.rafId) {
        cancelAnimationFrame(this.rafId);
        this.rafId = null;
      }
      if (this.bgIntervalId) {
        clearInterval(this.bgIntervalId);
        this.bgIntervalId = null;
      }
      this.releaseWakeLock();
      this.renderRoundDots();
      this.syncUI();
      return;
    }

    this.remainingMs = Math.max(0, seg.startMs + seg.durationMs - elapsedMs);
    this.syncUI();

    if (this.isRunning && document.visibilityState === 'visible') {
      if (this.rafId) cancelAnimationFrame(this.rafId);
      this.rafId = requestAnimationFrame(() => this.tick());
    }
  }

  updateMediaSession() {
    if ('mediaSession' in navigator && typeof MediaMetadata !== 'undefined') {
      try {
        navigator.mediaSession.metadata = new MediaMetadata({
          title: `Round ${this.currentRound} de ${this.config.totalRounds}`,
          artist: this.phase === 'REST' ? 'Descanso' : 'BOXTIMER PRO',
          album: 'Treino de Boxe'
        });
        navigator.mediaSession.setActionHandler('play', () => this.startTimer());
        navigator.mediaSession.setActionHandler('pause', () => this.pauseTimer());
      } catch (_) {}
    }
  }

  syncUI() {
    const activeStateClass = this.computeBodyStateClass();
    this.body.className = `${activeStateClass}${this.isRunning ? ' is-running' : ''}`;

    const hexColor = THEME_COLORS[activeStateClass] || '#090b10';
    if (this.themeMeta.getAttribute('content') !== hexColor) {
      this.themeMeta.setAttribute('content', hexColor);
    }

    this.roundDisplay.textContent = `ROUND ${this.currentRound} DE ${this.config.totalRounds}`;

    if (this.phase === 'IDLE') {
      this.phaseBadge.textContent = 'PRONTO PARA LUTAR';
    } else if (this.phase === 'PREP') {
      this.phaseBadge.textContent = 'PREPARE-SE';
    } else if (this.phase === 'WORK') {
      const secLeft = Math.ceil(this.remainingMs / 1000);
      if (this.config.warnLast10 && secLeft <= 10) {
        this.phaseBadge.textContent = '⚡ RETA FINAL • 10s ⚡';
      } else {
        this.phaseBadge.textContent = this.isRunning ? '🥊 ROUND ATIVO' : '⏸ ROUND PAUSADO';
      }
    } else if (this.phase === 'REST') {
      this.phaseBadge.textContent = this.isRunning ? '🧊 DESCANSO' : '⏸ DESCANSO PAUSADO';
    } else if (this.phase === 'FINISHED') {
      this.phaseBadge.textContent = '🏆 TREINO CONCLUÍDO!';
    }

    if (this.phase === 'FINISHED') {
      this.timeDisplay.textContent = 'FIM!';
    } else {
      this.timeDisplay.textContent = this.formatMMSS(this.remainingMs);
    }

    const ratio =
      this.phaseDurationMs > 0
        ? Math.max(0, Math.min(100, (this.remainingMs / this.phaseDurationMs) * 100))
        : 0;
    this.progressBar.style.width = `${ratio}%`;

    if (this.isRunning) {
      this.startPauseLabel.textContent = 'PAUSE';
      this.playIcon.classList.add('hidden');
      this.pauseIcon.classList.remove('hidden');
    } else {
      this.startPauseLabel.textContent =
        this.phase === 'IDLE' || this.phase === 'FINISHED' ? 'START' : 'RETOMAR';
      this.playIcon.classList.remove('hidden');
      this.pauseIcon.classList.add('hidden');
    }
  }

  computeBodyStateClass() {
    if (this.phase === 'IDLE') return 'state-idle';
    if (this.phase === 'PREP') return 'state-prep';
    if (this.phase === 'REST') return 'state-rest';
    if (this.phase === 'FINISHED') return 'state-finished';
    if (this.phase === 'WORK') {
      const secLeft = Math.ceil(this.remainingMs / 1000);
      if (this.config.warnLast10 && secLeft <= 10 && secLeft > 0) {
        return 'state-warning';
      }
      return 'state-work';
    }
    return 'state-idle';
  }

  renderRoundDots() {
    this.roundDots.innerHTML = '';
    const maxDots = Math.min(this.config.totalRounds, 15);
    for (let i = 1; i <= maxDots; i++) {
      const dot = document.createElement('span');
      dot.className = 'round-dot';
      if (i < this.currentRound || this.phase === 'FINISHED') {
        dot.classList.add('done');
      } else if (i === this.currentRound) {
        dot.classList.add('current');
      }
      this.roundDots.appendChild(dot);
    }
  }

  updateSummaryUI() {
    this.summaryRound.textContent = `🥊 ${this.formatMMSS(this.config.roundSeconds * 1000)}`;
    this.summaryRest.textContent = `🧊 ${this.formatMMSS(this.config.restSeconds * 1000)}`;
    this.summaryTotal.textContent = `🔄 ${this.config.totalRounds} ${this.config.totalRounds === 1 ? 'Round' : 'Rounds'}`;
    this.summaryWarn.classList.toggle('hidden', !this.config.warnLast10);
    this.summaryWarnSep.classList.toggle('hidden', !this.config.warnLast10);
  }

  formatMMSS(ms) {
    const totalSeconds = Math.ceil(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  triggerFlash() {
    this.flashOverlay.classList.add('active');
    setTimeout(() => {
      this.flashOverlay.classList.remove('active');
    }, 120);
  }

  vibrate(pattern) {
    if ('vibrate' in navigator) {
      try {
        navigator.vibrate(pattern);
      } catch (_) {}
    }
  }

  async requestWakeLock() {
    if ('wakeLock' in navigator) {
      try {
        this.wakeLock = await navigator.wakeLock.request('screen');
      } catch (_) {}
    }
  }

  async releaseWakeLock() {
    if (this.wakeLock) {
      try {
        await this.wakeLock.release();
      } catch (_) {}
      this.wakeLock = null;
    }
  }
}

window.addEventListener('DOMContentLoaded', () => {
  window.boxTimerApp = new BoxingTimerApp();

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker
      .register('./sw.js')
      .then((reg) => {
        reg.update();
      })
      .catch((err) => {
        console.warn('Falha ao registrar Service Worker:', err);
      });
  }
});
